#[path="../canonical-root/root.rs"]mod root;
use hec_native_ic::{fp::Fp,poly::Poly,jac::Curve,instance::factor_base,rng::Rng};
fn power(a:Poly,n:usize,f:&Fp)->Poly{let mut p=Poly::one();for _ in 0..n{p=p.mul(&a,f)}p}
fn norm(a:Poly,b:Poly,c:Poly,r:u64,f:&Fp)->Poly{let term=power(b,5,f).sub(&a.mul(&c,f).mul(&power(b,3,f),f).scale(5,f),f).add(&power(a,2,f).mul(&power(c,2,f),f).mul(&b,f).scale(5,f),f);power(c,5,f).add(&term.scale(r,f),f).add(&power(a,5,f).scale(f.mul(r,r),f),f)}
fn main(){let mut scalar=0;for p in[11,31]{let f=Fp::new(p);let z=root::power_map(&f,5).0;let rs:std::collections::BTreeSet<_>=(1..p).map(|x|f.pow(x,5)).collect();for r in rs{let x=(1..p).find(|&x|f.pow(x,5)==r).unwrap();for a in 0..p{for b in 0..p{for c in 0..p{let actual=norm(Poly::constant(a),Poly::constant(b),Poly::constant(c),r,&f);let(mut xx,mut expected)=(x,1);for _ in 0..5{expected=f.mul(expected,f.add(f.add(f.mul(a,f.mul(xx,xx)),f.mul(b,xx)),c));xx=f.mul(xx,z)}assert_eq!(actual,Poly::constant(expected));scalar+=1;}}}}println!("scalar_field={p} cumulative_cases={scalar}");}
let(mut panels,mut products,mut basepoints,mut distinct,mut degreefive)=(0,0,0,0,0);for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let f=&c.fp;let z=root::power_map(f,5).0;let fb=factor_base(&c);let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let mut anchor=c.mul(&d,k);let mut local=0;for _ in 0..16{anchor=c.add(&anchor,&d);if anchor.u.deg()!=2{continue}for &(x,y)in &fb{if x==0{continue}let r=f.pow(x,5);for yy in[y,f.neg(y)]{let actual=norm(Poly::from_coeffs(&[0,1]),Poly::from_coeffs(&[anchor.v.c[1],anchor.u.c[1]]),Poly::from_coeffs(&[f.sub(anchor.v.c[0],yy),anchor.u.c[0]]),r,f);let(mut xx,mut expected)=(x,Poly::one());let mut ts=std::collections::BTreeSet::new();let mut has_base=false;for _ in 0..5{let u=anchor.u.eval(xx,f);let v=anchor.v.eval(xx,f);if u==0&&v==yy{has_base=true;}if u!=0{ts.insert(f.mul(f.sub(yy,v),f.inv(u)));}expected=expected.mul(&Poly::from_coeffs(&[f.sub(v,yy),u]),f);xx=f.mul(xx,z);}assert_eq!(actual,expected);if has_base{assert!(actual.is_zero());basepoints+=1;}if actual.deg()==5{degreefive+=1;if ts.len()==5{distinct+=1;}}products+=1;local+=1;}}}panels+=1;println!("p={p} sm={sm} case={case} coefficient_products={local}");}}}assert_eq!(panels,12);assert!(basepoints>0&&distinct>0);println!("PASS scalar_cases={scalar} panels={panels} coefficient_products={products} basepoint_zero_products={basepoints} degree_five={degreefive} five_distinct_parameters={distinct} independent_verification=false");}
